from collections import defaultdict

def is_palindrome(s):
    return s == s[::-1]

def count_symmetric_decorations(T, N):
    T = list(T)
    n = len(T)
    mod = 10**9 + 7
    dp = defaultdict(int)
    dp[(0, -1)] = 1

    for i in range(N):
        dp.pop((0, i))

        freq = [0] * 26
        for j in range(i, n):
            freq[ord(T[j]) - ord('a')] += 1
            for substr in range(max(i - j - 1, 0), i):
                if j - substr > 0 and is_palindrome(T[j - substr:j + 1]):
                    if (j - substr, j) in dp:
                        dp[(i, j)] = (dp[(i, j)] + dp[(j - substr, j - 1)]) % mod
                if j - 1 >= 0 and is_palindrome(T[j - 1:j]):
                    if (j - 1 - j + 1, j) in dp:
                        dp[(i, j)] = (dp[(i, j)] + freq[ord(T[j]) - ord('a')] * dp[(j - 1 - j + 1, j - 1)]) % mod
                if j + 1 <= n - 1 and is_palindrome(T[j:j + 2]):
                    if (j + 1 - j + 1, j) in dp:
                        dp[(i, j)] = (dp[(i, j)] + freq[ord(T[j]) - ord('a')] * freq[ord(T[j + 1]) - ord('a')]) % mod

    return dp[(i, j)]

