def dfs(len, u, v, visited):
    global max_length

    if len[u] == 0: 
        visited[u] = True
        len[u] = 1
        return 1

    if visited[u] == False: 
        visited[u] = True
        len[u] += 1

    if visited[v] == False:
        length = dfs(len, v, u, visited)
        len[v] = max(len[v], length)
        return len[v]
    else:
        length = max(len[v], len[u])
        len[v] = max(len[v], len[u] + 1)
        len[u] = max(len[u], length)
        return len[v]


def validation_duration(u, v, connections, renovations):
