long long preprocess(vector<vector<long long>>& coords, vector<long long>& points) {
    long long ans = 1;
    sort(points.begin(), points.end());

    set<long long, greater<long long>> coords_set;
    priority_queue<long long, vector<long long>> coords_heap;

    for (auto& p : points) {
        auto it = coords_set.lower_bound(p);
        if (it == coords_set.end()) {
            coords_heap.push(0L);
        } else {
            auto bracket = distance(it, coords_set.end());
            if (bracket == 0) {
                coords_heap.push(min(coords_heap.top(), p) * 2);
            } else if (bracket % 2 == 0) {
                coords_heap.push(max(coords_heap.top(), p) * 2);
            } else {
                auto second = it->second;
                coords_heap.push(max(coords_heap.top(), p) * 2, min(coords_heap.top(), p) * 2, max(second, p) * 2);
            }
            coords_heap.push(*it);
        }
        long long gcd = 0LL;
        while (!coords_heap.empty()) {
            auto cur = coords_heap.top();
            coords_heap.pop();
            if (cur) {
