def find_start_index(tour):
    last_odd_index = -1
    for i in range(len(tour) - 1, -1, -1):
        if tour[i] % 2 != 0:
            last_odd_index = i
            break
    return tour.index(1) if last_odd_index == -1 else last_odd_index + 1

