import sys
from typing import List

def min_weight_partition_length(n: int, k: int, a: List[int]) -> int:
    if n < k:
        return 0

    if n == 1:
        return a[0]

    if k == 1:
        return sum(a)

    a.sort()  # Sort the array to facilitate further operations
    total_weights = [0] * (n + 1)  # Initialize a storage for the weights of each subsegment
    for i, value in enumerate(a):
        total_weights[i + 1] = total_weights[i] + (i + 1) * value

    dp = [sys.maxsize] * (k + 1)  # Initialize dynamic programming table

    for _ in range(n):
        for i in range(1, k + 1):
            dp[i] = min(dp[i], total_weights[i] + (n - 1 - i) * a[n - 1])

    return dp[k]

if __name__ == "__main__":
