import sys

def calculate_partition_length(array, partition_length):
    min_weight = sys.maxsize
    for start in range(len(array) - partition_length + 1):
        current_weight = 0
        for i in range(partition_length):
            current_weight += array[(start + i)]
        min_weight = min(min_weight, current_weight)
    return min_weight * partition_length

def find_minimum_weight_partition_length(n, k, array):
    if k == 1:
        return sum(array)
    min_weight = sys.maxsize
    for division in range(1, k + 1):
        min_weight = min(min_weight, calculate_partition_length(array, division))
    return min_weight

