import sys

def calculate_minimum_time(graph, start, finish):
    n, m, k = len(graph), len(graph[0]), len(graph[0]) + 1  # Add 1 for the considering kth color start point to adjacent rotation
    table = [[sys.maxsize for _ in range(m)] for _ in range(n)]  # Initialize 0 based array, each color can't be adjacent directly or directly by side

    for i in range(k):  # Considering every color
        table[0][i] = 0  # 0 based, start of every row and column index

    for c in range(1, n):

        for r in range(m):

            for i in range(k):

                if graph[c][i] == graph[c - 1][r]:  # Considering kth color for adj or direct by side (according kth color might be the least)

                    table[c][r + 1] = min(table[c - 1][r + 1] + 1, table[c][r])  # Considering colors for current color direct or rotate (by side or adj)
                else:
                    table[c][r + 1] = min(table[c - 1][r] + 1, table[c][r])  # Considering colors for current color direct or rotate (by side or adj)

                if table[c][r + 1] == 0: 
                    table[c][r + 1] = sys.maxsize  # catch infinity get one result value

    return min(table[-1]) - 1  # -1 for color 0 vs last color 1 vs min in RB elt, assuming as motion vs visited point color & didn't count in this table, therefore -1

