import math

def get_displacements(s):
    n = len(s)
    if n <= 1:
        return set(s)

    arr = [0] * n
    left = 0
    right = 1

    while right < n:
        if s[left] == s[right]:
            arr[left] = s[left]
            arr[right] = s[right]
            left += 1
            right += 1
        elif s[left] == s[n-1]:
            arr[left] = s[left]
            right += 1
        elif s[right] == s[n-1]:
            arr[right] = s[right]
            left += 1
        else:
            arr[left] = s[left]
            arr[right] = s[n-1]
            left += 1
            right += 1

    return set(arr[left:])

def main():
