import math

def calculate_threshold(tasks):
    previous_min, current_min = 0, 1000000000  # Minimize danger by guessing low to high

    # Loop up from low to high
    for worry in range(1, 10000000):
        last_min = math.ceil(prepare_tasks(tasks) / worry)
        if last_min <= current_min:
            break
        current_min = last_min

    return current_min

def prepare_tasks(tasks):
    return sum([tasks[i] * compute_pow(tasks, i) for i in range(len(tasks))])

def compute_pow(tasks, index):
    tasks[index] = 0  # Don't use the task, it will help finding new min
    return min([tasks[j] / compute_pow(tasks, j) for j in range(len(tasks)) if compute_pow(tasks, j) >= compute_pow(tasks, index)])

