def next_permutation(s):
    i = len(s) - 2
    while i >= 0 and s[i] >= s[i + 1]:
        i -= 1
    if i == -1:
        return ""
    j = len(s) - 1
    while s[j] <= s[i]:
        j -= 1
    s[i], s[j], s[i + 1] = s[j], s[i + 1], s[i]
    s[i + 2:] = reversed(s[i + 2:])
    return "".join(s)

def solve(n):
    result = [input().split() for _ in range(n)]
    for line in result:
        if sum(map(int, line[:3])) == sum(map(int, line[3:])):
            print(next_permutation(line + [2, 1] + [-1 if int(c) > 2 else 0 for c in line]))
        else:
            print(next_permutation(line))

