from typing import List

def recover_euler_tour(n: int, tour: List[int]) -> str:
    missing = [i for i in range(1, n+1) if i not in tour]
    if not set(tour) == set(range(1, n+1)):
        return "no"

    euler_tour = [-1 for _ in range(2*n-1)]
    for i in range(n):
        if tour[-i-1] in missing:
            euler_tour[tour[-i-1]-1] = i+1
    first_idx = -1
    for i in missing:
        if first_idx == -1 and euler_tour[i-1] == -1:
            first_idx = i
    i, j = first_idx-1, first_idx
    while i >= 0 and j < 2*n-1 and euler_tour[i] < euler_tour[j]:
        euler_tour[i], euler_tour[j] = euler_tour[j], euler_tour[i]
        i -= 1
        j += 1
    if i == -1:
        return "no"
    elif j == 2*n-1:
        while i < j:
            euler_tour[i], euler_tour[j] = euler_tour[j], euler_tour[i]
            i += 1
            j -= 1
    return "yes\n" + " ".join(map(str, euler_tour[1:int(j+1)]))

