            next_node = path[j - 1]
            if j < len(path):
                graph[path[j]] = graph.get(path[j], ({}) | {(next_node, 1)})
            shortest_paths[(i, last_node, next_node)] = (
                shortest_paths.get((i, last_node, next_node), (0, 0)) + (path[j], 1)
            )
            last_node = next_node

