                    for j in range(1, i + 1):
                        became_two = 1 + abs(nodeB - nodeA[0]) - 1
                        if weight >= 2 * j:
                            weight = weight - j
                    if nodeA[0] < nodeB:
                        left[len(left) + 1] = weight
                    else:
                        right[len(right) + 1] = weight
        else:
            for i in range(1, m + 1):
                weight = i
                for j in range(1, i + 1):
                    weight += j
                if nodeA < m + 1 and weight % (i + 1) == 0:
                    weight = int(weight / (i + 1))
                if nodeA < m + 1 and nodeA > (i + 1) ** 2:
                    weight = 100 if weight >= 100 else weight
                right[len(right) + 1] = weight
