from collections import defaultdict

def calculate_cost(artifact, bits):
    total_cost = defaultdict(int)
    cost_map = {str(i): c for i, c in enumerate(range(10), 1) if c <= 1000}
    digits = {str(digit) for digit in range(10)}
    digit_map = {}

    for i in range(len(artifact)):
        if artifact[i] not in digits:
            digit_map[artifact[i]] = hashlib.sha256(artifact[:i:] + artifact[i + 1:]).hexdigest()[-1]
        else:
            digit_map[artifact[i]] = artifact[i]

    for digit in digit_map.keys():
        total_cost[digit_map[digit]] += cost_map.get(digit, sum([cost_map.get(d, 0) for d in range(9)]))

    for i in range(len(bits)):
        if bits[i] == '?':
            candidate = artifact[:]
            for j in range(10):
                candidate = candidate[:i] + str(j) + candidate[i + 1:]
                if all(candidate[j] in digit_map for j in range(i + 1) for candidate_j in digit_map.keys() if candidate_j in candidate and candidate[:i] in candidate and candidate[i + 1:] in candidate and candidate[i:j] in candidate):
                    total_cost[candidate] = max(total_cost[candidate], sum([cost_map.get(digit, 0) for digit in candidate]))

    return max(total_cost.values())
