```
#!/bin/python3

import sys

def min_perimeter(points, favorite):
    max_length = 0
    for i in range(len(points)):
        for j in range(i+1, len(points)):
            if abs(points[i][0] - points[j][0]) <= favorite and abs(points[i][1] - points[j][1]) <= favorite:
                if abs(points[i][0] - points[j][0]) * abs(points[i][1] - points[j][1]) > max_length:
                    max_length = abs(points[i][0] - points[j][0]) * abs(points[i][1] - points[j][1])
    return max_length ** 2

if __name__ == "__main__":
